SELECT *
FROM t_counsel
WHERE counsel_type = 'VIRTUAL'
  AND virtual_id = #{virtualId}
  AND user_id = #{userId}
ORDER BY date_created;

SELECT *
FROM t_counsel
WHERE user_id = #{userId}
  AND counsel_type != 'VIRTUAL'
ORDER BY date_created DESC
LIMIT #{size} OFFSET #{page} * 10;

